import * as THREE from './vendor/three.module.js';
import {TangenzialeRace} from './tangenziale-race.js';
import {clamp,dist} from './core.js';
import {formatRaceTime} from './tangenziale-race-rules.js';

const BASE_START=TangenzialeRace.prototype.start;
const BASE_UPDATE=TangenzialeRace.prototype.update;
const BASE_UPDATE_AI=TangenzialeRace.prototype.updateAI;
const BASE_PAINT=TangenzialeRace.prototype.paintHud;
const BASE_RESTORE=TangenzialeRace.prototype.restoreSnapshot;

const mapColors=['#ffffff','#ff4f7d','#65d7ff','#f6cf55'];
function yawAt(samples,i){const a=samples[Math.max(0,i-1)],b=samples[Math.min(samples.length-1,i+1)];return Math.atan2(b.x-a.x,b.z-a.z);}
function localPoint(x,z,r){const dx=x-r.x,dz=z-r.z;return {u:dx*Math.cos(r.yaw)-dz*Math.sin(r.yaw),v:dx*Math.sin(r.yaw)+dz*Math.cos(r.yaw)};}
function trackY(game,p){const y=p?.road?game.terrain.roads?.sample?.(p.road,p.x,p.z):NaN;return Number.isFinite(y)?y+.055:(Number.isFinite(p.y)?p.y:game.terrain.height(p.x,p.z));}
function addBox(root,x,y,z,w,h,d,yaw,color,emissive=false){const mat=new THREE.MeshStandardMaterial({color,roughness:.45,metalness:.08,emissive:emissive?color:'#000000',emissiveIntensity:emissive?.55:0});const mesh=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat);mesh.position.set(x,y,z);mesh.rotation.y=yaw;mesh.receiveShadow=true;root.add(mesh);return mesh;}
function addRampMesh(root,r){const y0=r.topY[0],y1=r.topY[2],mesh=addBox(root,r.x,(y0+y1)*.5-.04,r.z,r.width,.2,r.length,r.yaw,r.bridgeJump?'#d8582e':'#c28a35');mesh.rotation.order='YXZ';mesh.rotation.x=-Math.atan2(r.rise,r.length);return mesh;}
function addBoostPad(root,r){const behind=r.length/2+4.6,s=Math.sin(r.yaw),c=Math.cos(r.yaw),cx=r.x-s*behind,cz=r.z-c*behind,y=r.topY[0]+.035;for(let i=0;i<6;i++){const along=(i-2.5)*.72,x=cx+s*along,z=cz+c*along;addBox(root,x,y,z,r.width*.82,.04,.30,r.yaw,i%2?'#5ee7ff':'#f4e85b',true);}r.boostPad={x:cx,z:cz,yaw:r.yaw,width:r.width*.92,length:5.2,used:false};}
function findBridgeApproaches(race){const out=[];let inBridge=false;for(let i=race.startIndex+10;i<race.samples.length-10;i++){const road=race.samples[i].road,isBridge=!!road&&(!!road.b||!!road.crossing||Number(road.layer)>0);if(isBridge&&!inBridge){const idx=Math.max(race.startIndex+7,i-4);if(!out.length||idx-out.at(-1)>22)out.push(idx);if(out.length>=2)break;}inBridge=isBridge;}return out;}
function addBridgeJumpRamps(manager){const race=manager.race;if(!race||race.__bridgeJumpRamps)return;race.__bridgeJumpRamps=true;const root=new THREE.Group();root.name='tangenziale-bridge-jump-ramps';for(const index of findBridgeApproaches(race)){const p=race.samples[index],yaw=yawAt(race.samples,index),y=trackY(manager.game,p),r={kind:'tangenziale-race-ramp',tangenzialeRace:true,bridgeJump:true,x:p.x,z:p.z,yaw,width:5.4,length:13.5,rise:2.05,topY:[y,y,y+2.05,y+2.05],boostPad:null};race.ramps.push(r);manager.game.terrain.arcadeRamps.push(r);addRampMesh(root,r);}if(root.children.length){manager.game.scene.add(root);race.roots.push(root);}else root.clear();}
function decorateRamps(manager){const race=manager.race;if(!race||race.__boostPads)return;race.__boostPads=true;addBridgeJumpRamps(manager);const root=new THREE.Group();root.name='tangenziale-race-boost-pads';for(const r of race.ramps)addBoostPad(root,r);manager.game.scene.add(root);race.roots.push(root);race.playerRampBoostUntil=0;race.lastBoostRamp=null;}
function applyRampBoost(manager){const race=manager.race,state=manager.game.state;if(!race||race.phase!=='running'||race.playerFinished)return;for(const r of race.ramps){const pad=r.boostPad;if(!pad||pad.used)continue;const q=localPoint(state.x,state.z,{...pad,x:pad.x,z:pad.z,yaw:pad.yaw});if(Math.abs(q.u)>pad.width/2||Math.abs(q.v)>pad.length/2)continue;pad.used=true;race.lastBoostRamp=r;race.playerRampBoostUntil=state.elapsed+(r.bridgeJump?2.2:1.55);const cap=race.playerCar.spec.max*(r.bridgeJump?1.34:1.22),gain=r.bridgeJump?13:9.5;state.speed=Math.min(cap,Math.max(state.speed+gain,race.playerCar.spec.max*.96));race.playerCar.speed=state.speed;manager.game.toast(r.bridgeJump?'BOOST PONTE · SALTO LUNGO':'BOOST RAMPA · VANTAGGIO VELOCITÀ',1.7);}
 if(state.elapsed<race.playerRampBoostUntil){const cap=race.playerCar.spec.max*(race.lastBoostRamp?.bridgeJump?1.34:1.22);state.speed=Math.min(cap,state.speed+.11);race.playerCar.speed=state.speed;}
 const jump=race.playerCar.jump,last=race.lastBoostRamp;if(jump?.airborne&&last&&!last.__airBoosted&&dist(state,last)<28){last.__airBoosted=true;const factor=last.bridgeJump?1.12:1.07;jump.vx*=factor;jump.vz*=factor;jump.vy=Math.max(jump.vy,last.bridgeJump?7.2:5.4);}
}
function keepRivalsCompetitive(manager){const r=manager.race;if(!r||r.phase!=='running')return;for(const [i,c] of r.ai.entries()){if(c.raceFinished)continue;const gap=r.playerProgress-(c.raceProgress||0),targetSkill=1.005+clamp(gap/1500,-.055,.095)+i*.004;c.raceSkill+=(targetSkill-c.raceSkill)*.08;if(gap>820||dist(c,r.playerCar)>1450&&gap>250){const idx=clamp((r.playerHint||r.startIndex)-5-i*2,r.startIndex,r.samples.length-4);manager.respawnActor(c,idx,c.raceOffset);c.raceHint=idx;c.raceCheckpoint=idx;c.raceProgress=Math.max(c.raceProgress||0,Math.max(0,r.playerProgress-140-i*45));c.raceTurbo=Math.max(c.raceTurbo||0,1);}}
}
function raceBoard(manager){const r=manager.race;if(!r)return '';const progress=[r.playerProgress,...r.ai.map(c=>c.raceProgress||0)];return progress.map((p,i)=>{const place=r.finishOrder.indexOf(i),time=r.finishTimes[i],pct=Math.round(Math.min(100,p/r.total*100)),status=time!==null?('#'+(place+1)+' · '+formatRaceTime(time)):('IN GARA · '+pct+'% percorso');return '<div><strong>'+(i===0?'AUTO 1 · TU':'AUTO '+(i+1))+'</strong><span style="float:right;margin-left:18px">'+status+'</span></div>';}).join('');}
function ensureMiniMap(manager){const r=manager.race;if(!r||typeof document==='undefined')return null;const ui=document.getElementById('tangenzialeRaceUi');if(!ui)return null;let box=ui.querySelector('#tangenzialeCourseBox');if(!box){box=document.createElement('div');box.id='tangenzialeCourseBox';box.style.cssText='position:absolute;left:18px;top:82px;width:238px;background:rgba(10,14,18,.80);border:1px solid rgba(255,255,255,.22);border-radius:12px;padding:9px 10px 8px;box-sizing:border-box';box.innerHTML='<div style="font-size:10px;letter-spacing:.08em;opacity:.72;margin-bottom:5px">PERCORSO COMPLETO · '+(r.total/1000).toFixed(1)+' km</div><canvas id="tangenzialeCourseMap" width="216" height="148" style="width:216px;height:148px;display:block"></canvas><div style="font-size:10px;opacity:.68;margin-top:4px">● tu &nbsp; ● avversari &nbsp; linea = tracciato</div>';ui.appendChild(box);}return box.querySelector('#tangenzialeCourseMap');}
function drawMiniMap(manager){const r=manager.race,canvas=ensureMiniMap(manager);if(!r||!canvas)return;const ctx=canvas.getContext('2d'),path=r.samples.slice(r.startIndex);if(!ctx||path.length<2)return;const xs=path.map(p=>p.x),zs=path.map(p=>p.z),minX=Math.min(...xs),maxX=Math.max(...xs),minZ=Math.min(...zs),maxZ=Math.max(...zs),pad=10,w=canvas.width-pad*2,h=canvas.height-pad*2,spanX=Math.max(1,maxX-minX),spanZ=Math.max(1,maxZ-minZ),scale=Math.min(w/spanX,h/spanZ),ox=(canvas.width-spanX*scale)/2,oy=(canvas.height-spanZ*scale)/2,pt=p=>({x:ox+(p.x-minX)*scale,y:canvas.height-(oy+(p.z-minZ)*scale)});ctx.clearRect(0,0,canvas.width,canvas.height);ctx.lineWidth=3;ctx.strokeStyle='rgba(255,255,255,.58)';ctx.beginPath();path.forEach((p,i)=>{const q=pt(p);i?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y);});ctx.stroke();const finish=pt(r.finish);ctx.strokeStyle='#f4e85b';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(finish.x-5,finish.y);ctx.lineTo(finish.x+5,finish.y);ctx.stroke();[r.playerCar,...r.ai].forEach((c,i)=>{const q=pt(c);ctx.fillStyle=mapColors[i]||'#fff';ctx.beginPath();ctx.arc(q.x,q.y,i===0?4.4:3.6,0,Math.PI*2);ctx.fill();ctx.strokeStyle='rgba(0,0,0,.7)';ctx.lineWidth=1;ctx.stroke();});}

TangenzialeRace.prototype.raceBoard=function(){return raceBoard(this);};
TangenzialeRace.prototype.start=function(...args){const out=BASE_START.apply(this,args);if(this.race){decorateRamps(this);queueMicrotask(()=>drawMiniMap(this));}return out;};
TangenzialeRace.prototype.updateAI=function(dt){keepRivalsCompetitive(this);return BASE_UPDATE_AI.call(this,dt);};
TangenzialeRace.prototype.paintHud=function(center=null){BASE_PAINT.call(this,center);queueMicrotask(()=>{if(!this.race)return;const board=document.getElementById('tangenzialeBoard');if(board){const label=board.firstElementChild;if(label)label.textContent='TEMPO FINALE / AVANZAMENTO';}const desc=document.getElementById('missionDesc');if(desc)desc.textContent='Fulmine R · Turbo '+this.race.playerTurbo+'/3 · SHIFT · X abbandona · '+Math.round(Math.min(100,this.race.playerProgress/this.race.total*100))+'% percorso completato';drawMiniMap(this);});};
TangenzialeRace.prototype.update=function(dt){const out=BASE_UPDATE.call(this,dt);applyRampBoost(this);return out;};
TangenzialeRace.prototype.restoreSnapshot=function(...args){const race=this.race,out=BASE_RESTORE.apply(this,args);if(race)for(const r of race.ramps||[])r.__airBoosted=false;return out;};
